steps.command:
sbx run <<'EOF'
cd /workspace
cat > /workspace/probe/fuzz.py <<'PYEOF'
import os, random, subprocess, sys

BASE = "/workspace"
ORIG = os.path.join(BASE, "probe", "orig")
ACCT = os.path.join(BASE, "data", "ACCOUNTS.DAT")
BOOKS = os.path.join(BASE, "data", "BOOKS.DAT")
TRANS = os.path.join(BASE, "data", "TRANSACTIONS.DAT")
INPUT = os.path.join(BASE, "src", "INPUT.DAT")

def read(p):
    with open(p, "rb") as f: return f.read()

orig = {n: read(os.path.join(ORIG, n)) for n in
        ("ACCOUNTS.DAT", "BOOKS.DAT", "TRANSACTIONS.DAT")}
orig_input = read(os.path.join(ORIG, "INPUT.DAT"))

def reset(datafiles):
    for name, path in (("ACCOUNTS.DAT", ACCT), ("BOOKS.DAT", BOOKS),
                       ("TRANSACTIONS.DAT", TRANS)):
        with open(path, "wb") as f:
            f.write(datafiles.get(name, orig[name]))

def snapshot():
    return {n: read(p) for n, p in (("ACCOUNTS.DAT", ACCT), ("BOOKS.DAT", BOOKS),
                                    ("TRANSACTIONS.DAT", TRANS))}

def run(cmd):
    p = subprocess.run(cmd, cwd=BASE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.returncode, p.stdout, p.stderr

ACCT_IDS = ["U001", "U002", "U003", "U004", "U005"]
BOOK_IDS = ["B001", "B002", "B003", "B004", "B005"]

def rand_amount_field(rng):
    style = rng.randrange(5)
    if style == 0:
        return ("%010d" % rng.randrange(10**10)).encode()
    if style == 1:
        n = rng.randrange(0, 11)
        return ("".join(rng.choice("0123456789") for _ in range(n))).encode()
    if style == 2:
        # right-aligned digits padded with spaces
        s = "".join(rng.choice("0123456789") for _ in range(rng.randrange(0, 8)))
        return (s.rjust(10)).encode()
    if style == 3:
        # spaces scattered
        s = list(("%010d" % rng.randrange(10**10)))
        for _ in range(rng.randrange(1, 4)):
            s[rng.randrange(10)] = " "
        return "".join(s).encode()
    return bytes(rng.choice(b"0123456789 ") for _ in range(10))

def rand_accounts(rng):
    out = bytearray()
    for _ in range(rng.randrange(0, 7)):
        aid = rng.choice(ACCT_IDS)
        name = "".join(rng.choice("ABCdef 0123") for _ in range(20)).encode()
        bal = ("%010d" % rng.choice([rng.randrange(10**10), 0, 1800, 1520, 1180])).encode()
        out += aid.encode() + name + bal
    if out and rng.random() < 0.2:
        out = out[:len(out) - rng.randrange(1, 9)]
    return bytes(out)

def rand_books(rng):
    out = bytearray()
    for _ in range(rng.randrange(0, 7)):
        bid = rng.choice(BOOK_IDS)
        title = "".join(rng.choice("ABCdef 0123") for _ in range(20)).encode()
        owner = rng.choice(ACCT_IDS).encode()
        out += bid.encode() + title + owner
    if out and rng.random() < 0.2:
        out = out[:len(out) - rng.randrange(1, 9)]
    return bytes(out)

def rand_transactions(rng):
    out = bytearray()
    for _ in range(rng.randrange(0, 5)):
        out += (rng.choice(BOOK_IDS).encode() + ("%010d" % rng.randrange(10**10)).encode()
                + rng.choice(ACCT_IDS).encode() + rng.choice(ACCT_IDS).encode())
    if out and rng.random() < 0.15:
        out = out[:len(out) - rng.randrange(1, 9)]
    return bytes(out)

def rand_input(rng):
    buyer = rng.choice(ACCT_IDS + ["U009", "    "]).encode()
    seller = rng.choice(ACCT_IDS + ["U009", "    "]).encode()
    book = rng.choice(BOOK_IDS + ["B009", "    "]).encode()
    amount = rand_amount_field(rng)
    rec = buyer + seller + book + amount
    style = rng.randrange(6)
    if style == 0:
        rec = rec[:rng.randrange(0, 23)]          # truncate anywhere
    elif style == 1:
        rec = rec + bytes(rng.choice(b"XYZ012") for _ in range(rng.randrange(1, 12)))
    return rec

rng = random.Random(20261101)
fails = 0
N = 400
for i in range(N):
    datafiles = {"ACCOUNTS.DAT": rand_accounts(rng),
                 "BOOKS.DAT": rand_books(rng),
                 "TRANSACTIONS.DAT": rand_transactions(rng)}
    inp = rand_input(rng)
    reset(datafiles)
    with open(INPUT, "wb") as f: f.write(inp)
    c = run(["/workspace/probe/bookforum"]); cf = snapshot()
    reset(datafiles)
    with open(INPUT, "wb") as f: f.write(inp)
    p = run([sys.executable, "/workspace/program.py"]); pf = snapshot()
    if c != p or cf != pf:
        fails += 1
        print(f"FAIL case {i}")
        print("  input:", inp)
        print("  data:", {k: v for k, v in datafiles.items()})
        print("  rc/out/err cobol:", c)
        print("  rc/out/err py   :", p)
        for k in cf:
            if cf[k] != pf[k]:
                a, b = cf[k], pf[k]
                pos = next((j for j in range(min(len(a), len(b))) if a[j] != b[j]),
                           min(len(a), len(b)))
                print(f"  {k} diff at {pos}: cobol={a[pos:pos+24]!r}(len{len(a)}) "
                      f"py={b[pos:pos+24]!r}(len{len(b)})")
        if fails >= 8:
            break

print(f"{fails} failures out of {i+1} fuzz cases")
reset({})
with open(INPUT, "wb") as f: f.write(orig_input)
PYEOF
python3 /workspace/probe/fuzz.py
